-- Fișierul se rulează automat de database.py, o singură dată, când nu există podcasts.db.
-- link = căutare pe Spotify, youtube_link = căutare pe YouTube (le poți înlocui cu linkurile directe).
-- voxa_link e gol: completează-l doar pentru podcasturile pe care le găsești în Voxa; butonul apare doar dacă e completat.

-- 1. Tabelul de podcasturi
create table podcasts (
  id          integer primary key autoincrement,
  title       text not null,
  author      text not null,
  category    text not null,
  description text not null,
  link        text not null default '',
  youtube_link text not null default '',
  voxa_link   text not null default ''
);

